const storageKey = 'personal-engineering-os-state';
const initialState = { theme:'dark', fontScale:'normal', user:null, registeredUsers:[], selectedCourses:['dsa','web','net'], primary:'dsa', activeCourse:'dsa', progress:{'dsa:1:0':true,'dsa:1:1':true,'dsa:1:2':true,'dsa:2:0':true,'dsa:2:1':true,'web:0:0':true,'web:0:1':true}, layout:'grid', sound:'rain', focusSeconds:1500, isFocusing:false, quoteIndex:0, openChapter:1 };
let state = loadState(); let focusInterval; let currentView = state.user ? 'dashboard' : 'landing';
function loadState(){ try { return {...initialState,...JSON.parse(localStorage.getItem(storageKey))}; } catch { return {...initialState}; } }
function saveState(){ localStorage.setItem(storageKey,JSON.stringify(state)); }
function esc(str=''){return String(str).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function initials(name='Student'){return name.split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();}
function courseById(id){return courseCatalog.find(c=>c.id===id)||courseCatalog[0];}
function detailFor(id){return courseDetails[id]||genericDetail;}
function key(id,chapter,topic){return `${id}:${chapter}:${topic}`;}
function totalTopics(id){return detailFor(id).reduce((n,c)=>n+c.topics.length,0);}
function completedTopics(id){return detailFor(id).flatMap((c,ci)=>c.topics.map((_,ti)=>state.progress[key(id,ci,ti)])).filter(Boolean).length;}
function percent(id){return Math.round(completedTopics(id)/totalTopics(id)*100);}
function globalPercent(){const ids=state.selectedCourses;return ids.length?Math.round(ids.reduce((n,id)=>n+percent(id),0)/ids.length):0;}
function icon(name){return ICONS[name]||'';}
function render(){document.body.classList.toggle('light',state.theme==='light');document.documentElement.style.setProperty('--font-size',{small:'14px',normal:'16px',large:'18px',xlarge:'20px'}[state.fontScale]);document.getElementById('app').innerHTML=state.user?dashboard():landing();bindEvents();}
function commonTopbar(dashboard=false){return dashboard ? `<header class="dash-nav shell"><a class="brand" href="#" data-action="home"><span class="brand-mark">${icon('leaf')}</span><span>Engineering OS</span></a><nav class="dash-menu" aria-label="Dashboard"><button class="nav-link active" data-scroll="learn">Learning Space</button><button class="nav-link" data-action="assessments">Assessments</button><button class="nav-link" data-action="projects">Blueprint Hub</button></nav><div class="nav-tools"><button class="icon-button" data-action="theme" aria-label="Toggle colour theme">${state.theme==='dark'?icon('sun'):icon('moon')}</button><button class="scale-button ${state.fontScale==='small'?'active':''}" data-scale="small">A−</button><button class="scale-button ${state.fontScale==='normal'?'active':''}" data-scale="normal">A</button><button class="scale-button ${state.fontScale==='large'?'active':''}" data-scale="large">A+</button><button class="scale-button ${state.fontScale==='xlarge'?'active':''}" data-scale="xlarge">A++</button><button class="profile" data-action="profile" aria-label="Open profile"><span class="avatar">${initials(state.user.name)}</span><span class="profile-text"><small>LEARNER</small><strong>${esc(state.user.name)}</strong></span></button></div></header>` : `<header class="topbar shell"><a class="brand" href="#"><span class="brand-mark">${icon('leaf')}</span><span>Personal Engineering OS</span></a><div class="nav-tools"><button class="icon-button" data-action="theme" aria-label="Toggle colour theme">${state.theme==='dark'?icon('sun'):icon('moon')}</button><button class="scale-button ${state.fontScale==='small'?'active':''}" data-scale="small">A−</button><button class="scale-button ${state.fontScale==='normal'?'active':''}" data-scale="normal">A</button><button class="scale-button ${state.fontScale==='large'?'active':''}" data-scale="large">A+</button><button class="scale-button ${state.fontScale==='xlarge'?'active':''}" data-scale="xlarge">A++</button><button class="icon-button only-mobile" data-action="login" aria-label="Sign in">${icon('arrow')}</button></div></header>`;}
function landing(){const q=quotes[state.quoteIndex];return `<div class="shell">${commonTopbar()}<section class="hero"><video class="hero-video" autoplay muted loop playsinline poster="" aria-hidden="true"><source src="https://videos.pexels.com/video-files/3195394/3195394-uhd_2560_1440_25fps.mp4" type="video/mp4"></video><div class="hero-fallback" aria-hidden="true"></div><div class="hero-overlay" aria-hidden="true"></div><div class="hero-content"><div><div class="eyebrow">A calmer way to engineer</div><h1>Find your <em>focus.</em><br>Build your future.</h1><p class="hero-copy">A personal learning system built for the way engineers really work: one topic, one session, one meaningful milestone at a time.</p><div class="cta-row"><button class="button primary" data-action="login">Start Learning Courses ${icon('arrow')}</button><button class="button ghost" data-action="scroll-paths">Explore your path</button></div></div><aside class="quote-card" aria-live="polite"><div>${icon('quote')}</div><div class="quote-text" id="quote-text">“${q[0]}”</div><div class="quote-by"><span>${q[1]}</span><span class="ticker-dots">${quotes.map((_,i)=>`<span class="${i===state.quoteIndex?'active':''}"></span>`).join('')}</span></div></aside></div><div class="login-paths" id="login-paths"><button class="path-card" data-login-type="new"><span class="path-label">01 · New here</span><strong>I’m starting my learning journey</strong><span>Set up your branch, degree and first course.</span></button><button class="path-card" data-login-type="returning"><span class="path-label">02 · Welcome back</span><strong>I’m continuing my learning</strong><span>Pick up exactly where your last study session ended.</span></button></div><footer class="landing-footer"><span><i class="status-dot"></i> Your progress stays with you</span><span>LOCAL-FIRST LEARNING SPACE</span></footer></section></div>`;}
function courseCard(c){const p=percent(c.id);const isPrimary=state.primary===c.id;return `<article class="course-card bento ${c.id===state.activeCourse?'selected':''}" style="--course-accent:${c.accent}" data-course="${c.id}"><div class="course-orb"></div><div class="course-top"><div><div class="course-code">${c.code} · ${c.branch}</div><h4>${c.title}</h4></div><button class="more" aria-label="Course options">•••</button></div><div class="topic-preview"><strong>Up next</strong><br>${c.current}</div><div class="course-bottom"><div class="course-progress"><div class="progress-track"><span style="width:${p}%"></span></div><span>${p}% complete · ${completedTopics(c.id)}/${totalTopics(c.id)} topics</span></div><button class="primary-toggle ${isPrimary?'active':''}" data-action="primary" data-course="${c.id}">${isPrimary?'Primary':'Set primary'}</button></div></article>`;}
function dashboard(){const active=courseById(state.activeCourse);const p=percent(active.id);const hours=Math.max(0,Math.round(completedTopics(active.id)*.75));return `<div class="dashboard">${commonTopbar(true)}<main class="shell dashboard-main"><section><div class="dashboard-greeting"><div><div class="eyebrow">My learning space</div><h2>Good ${getGreeting()}, ${esc(state.user.name.split(' ')[0])}.</h2></div><button class="button primary" data-action="drawer">${icon('plus')} Add courses</button></div><article class="today-card bento"><div class="date-pod"><span>Today’s focus</span><strong>${active.title}</strong></div><div class="continue-info"><div class="micro muted">CONTINUE WHERE YOU LEFT OFF</div><h3>${active.current}</h3><div class="progress-track"><span style="width:${p}%"></span></div><div class="progress-line"><span>Semester ${active.id==='dsa'?'3':'4'} · ${completedTopics(active.id)} topics complete</span><span>${p}%</span></div></div><div class="circle-progress" style="--p:${p}"><strong>${p}%</strong></div></article><div class="section-head"><div><h3>Your course board</h3><p>Curricula grounded in the Engineering Master Curriculum.</p></div><div class="inline-controls"><button class="segment ${state.layout==='grid'?'active':''}" data-layout="grid" aria-label="Grid layout">${icon('grid')}</button><button class="segment ${state.layout==='list'?'active':''}" data-layout="list" aria-label="List layout">${icon('list')}</button></div></div><div class="course-grid ${state.layout}">${state.selectedCourses.length?state.selectedCourses.map(id=>courseCard(courseById(id))).join(''):`<div class="empty-courses">Your workspace is waiting for its first course.<br><button class="button primary" data-action="drawer">${icon('plus')} Discover courses</button></div>`}</div><section class="workspace-area" id="learn">${state.selectedCourses.length?learningSpace(active):''}</section></section><aside class="side-stack">${focusCard()}<article class="side-card bento"><h3>Small wins, growing roots</h3><div class="habit-list"><div class="habit"><i class="habit-dot done"></i>Open a lesson <span>done</span></div><div class="habit"><i class="habit-dot ${completedTopics(active.id)>0?'done':''}"></i>Finish a topic <span>${completedTopics(active.id)?'done':'next'}</span></div><div class="habit"><i class="habit-dot"></i>Review with a card <span>5 min</span></div></div></article><article class="side-card bento"><h3>Learning pulse</h3><div class="mini-stat-grid"><div class="mini-stat"><strong>${globalPercent()}%</strong><span>overall progress</span></div><div class="mini-stat"><strong>${hours}h</strong><span>deep study</span></div><div class="mini-stat"><strong>${state.selectedCourses.length}</strong><span>active courses</span></div><div class="mini-stat"><strong>3</strong><span>day rhythm</span></div></div></article></aside></main></div>`;}
function focusCard(){let seconds=state.focusSeconds;let m=String(Math.floor(seconds/60)).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');return `<article class="side-card focus-card bento"><div class="focus-top"><div><div class="micro" style="color:#adbfad">FOCUS DECK</div><h3 style="margin:5px 0 0">${seconds<=300?'Short break':'25 minute session'}</h3></div>${icon('timer')}</div><div class="focus-clock">${m}:${s}</div><div class="focus-controls"><button class="round-button main" data-action="focus">${state.isFocusing?icon('pause'):icon('play')}</button><button class="round-button" data-action="focus-reset" aria-label="Reset focus timer">↺</button></div><div class="ambient"><button class="${state.sound==='rain'?'active':''}" data-sound="rain">Rain</button><button class="${state.sound==='lofi'?'active':''}" data-sound="lofi">Lo-fi</button><button class="${state.sound==='white'?'active':''}" data-sound="white">White noise</button></div></article>`;}
function learningSpace(course){const details=detailFor(course.id);return `<div class="workspace-tabs">${state.selectedCourses.map(id=>{let c=courseById(id);return `<button class="workspace-tab ${id===course.id?'active':''}" data-course="${id}">${c.title}</button>`}).join('')}</div><div class="study-layout"><article class="learning-card bento"><div class="learning-card-head"><div><div class="micro muted">SEMESTER ${course.id==='dsa'?'03':'04'} · ${course.code}</div><h3>Course map</h3></div><span class="tag">${percent(course.id)}% mastered</span></div><div class="chapter-list">${details.map((ch,ci)=>chapter(course.id,ch,ci)).join('')}</div></article><article class="now-card bento"><div class="micro muted">NOW LEARNING</div><h3>${course.current}</h3><div class="video-frame"><div class="video-grid"></div><button class="play-large" data-action="video" aria-label="Play topic lecture">${icon('play')}</button></div><div class="now-meta"><span>▶ 12:43 lecture</span><span>◌ 4 prerequisites</span></div><div class="resource-buttons"><button class="resource-button" data-action="resource">${icon('book')} Notes</button><button class="resource-button" data-action="resource">${icon('external')} Reference</button><button class="resource-button" data-action="resource">${icon('check')} Quick practice</button></div></article></div><div class="tool-shelf"><article class="tool-card bento"><div class="tool-icon">${icon('cards')}</div><h3>Flashcard studio</h3><p>Turn chapter knowledge into recall that sticks.</p><button class="text-button" data-action="flashcards">Review a card →</button></article><article class="tool-card bento"><div class="tool-icon">${icon('code')}</div><h3>Code & math sandbox</h3><p>Run compact JavaScript experiments beside your notes.</p><button class="text-button" data-action="sandbox">Open sandbox →</button></article><article class="tool-card bento"><div class="tool-icon">${icon('folder')}</div><h3>Blueprint hub</h3><p>Build from starter kits, pinouts and project guides.</p><button class="text-button" data-action="projects">Explore projects →</button></article></div>`;}
function chapter(id,ch,ci){let done=ch.topics.filter((_,ti)=>state.progress[key(id,ci,ti)]).length;let isOpen=state.openChapter===ci;return `<div class="chapter ${isOpen?'open':''}"><button class="chapter-button" data-action="chapter" data-chapter="${ci}"><i class="chapter-bullet"></i><span class="chapter-title">${ch.title}</span><span class="chapter-pct">${done}/${ch.topics.length}</span>${icon('chevron')}</button><div class="topics">${ch.topics.map((t,ti)=>`<label class="topic"><input type="checkbox" data-action="topic" data-chapter="${ci}" data-topic="${ti}" ${state.progress[key(id,ci,ti)]?'checked':''}><span>${t}</span></label>`).join('')}</div></div>`;}
function getGreeting(){let h=new Date().getHours();return h<12?'morning':h<18?'afternoon':'evening';}
function loginModal(type='new'){return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="login-title" onclick="event.stopPropagation()"><button class="close" data-action="close-modal" aria-label="Close">${icon('close')}</button><div class="eyebrow">Your learning space</div><h2 id="login-title">${type==='new'?'Let’s make this yours.':'Welcome back.'}</h2><p>${type==='new'?'A few details help us shape your first course board.':'Restore your courses, preferences and last learning moment.'}</p><div class="login-options"><button class="login-option ${type==='new'?'selected':''}" data-login-type="new"><strong>01 · Start learning</strong><span>Create your personalised workspace.</span></button><button class="login-option ${type==='returning'?'selected':''}" data-login-type="returning"><strong>02 · Continue learning</strong><span>Return to your saved progress.</span></button></div><form id="login-form"><input type="hidden" name="mode" value="${type}"><div class="form-grid"><div class="field ${type==='returning'?'full':''}"><label for="email">College email</label><input id="email" name="email" type="email" placeholder="you@college.edu" required value="${type==='returning'?'student@college.edu':''}"></div>${type==='new'?`<div class="field"><label for="name">Full name</label><input id="name" name="name" placeholder="Your name" required></div><div class="field"><label for="degree">Degree</label><select id="degree" name="degree"><option>B.Tech</option><option>B.Sc</option><option>Diploma</option><option>M.Tech</option></select></div><div class="field"><label for="branch">Branch</label><select id="branch" name="branch"><option>CSE</option><option>ECE</option><option>EEE</option><option>Mechanical</option><option>Civil</option><option>Multi-disciplinary</option></select></div><div class="field full"><label for="college">College name <span class="muted">(optional)</span></label><input id="college" name="college" placeholder="Your institution"></div>`:''}</div><div class="form-note">${icon('lock')} <span>Demo mode stores your preferences locally. Connect your Google Sheets, Gmail and WhatsApp service via the integration adapter before production.</span></div><button class="button primary" type="submit">${type==='new'?'Create my learning space':'Restore my learning space'} ${icon('arrow')}</button><div class="modal-footer">Your study rhythm is private, portable and always yours.</div></form></div></div>`;}
function drawer(){let branches=[...new Set(courseCatalog.map(c=>c.branch).filter(b=>b!=='All branches'))],degrees=[...new Set(courseCatalog.map(c=>c.degree))];return `<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-head"><div><div class="eyebrow">Course discovery</div><h2 id="drawer-title">Build your board.</h2><p class="muted" style="font-size:.76rem;margin:5px 0 0">Filter the master curriculum by degree, branch or skill.</p></div><button class="close" data-action="close-drawer" aria-label="Close">${icon('close')}</button></div><div class="filter-row"><input type="search" id="course-search" placeholder="Search topics or courses"><select id="degree-filter"><option value="all">All degrees</option>${degrees.map(d=>`<option value="${esc(d)}">${d}</option>`).join('')}</select><select id="branch-filter"><option value="all">All branches</option>${branches.map(b=>`<option value="${esc(b)}">${b}</option>`).join('')}</select><select id="skill-filter"><option value="all">All skill areas</option>${[...new Set(courseCatalog.map(c=>c.skill))].map(s=>`<option value="${esc(s)}">${s}</option>`).join('')}</select></div><div class="catalog-list" id="catalog-list">${catalogItems(courseCatalog)}</div><div class="drawer-footer"><button class="button primary" data-action="close-drawer">${icon('check')} ${state.selectedCourses.length} course${state.selectedCourses.length===1?'':'s'} on my board</button></div></aside>`;}
function catalogItems(list){return list.map(c=>`<article class="catalog-item"><span class="catalog-icon" style="--catalog-color:${c.accent}">${icon(c.skill==='Development'?'code':c.skill==='AI & Data'?'spark':'book')}</span><div class="catalog-detail"><strong>${c.title}</strong><span>${c.degree} · ${c.branch} · ${c.description}</span></div><button class="add-course ${state.selectedCourses.includes(c.id)?'added':''}" data-action="add-course" data-course="${c.id}">${state.selectedCourses.includes(c.id)?'Added':'Add +'}</button></article>`).join('')||'<p class="muted" style="text-align:center;padding:25px">No courses match that filter.</p>'}
function assessmentModal(){return `<div class="modal-backdrop" data-action="close-modal"><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="assessment-title" onclick="event.stopPropagation()"><button class="close" data-action="close-modal" aria-label="Close">${icon('close')}</button><div class="eyebrow">Semester checkpoint</div><h2 id="assessment-title">Test your signal, not your stress.</h2><p>Quick diagnostic for ${courseById(state.activeCourse).title}. Completion creates a performance summary in your learning log.</p><div class="quiz-grid"><div><div class="quiz-question"><p><strong>01.</strong> Which traversal explores a binary tree level by level?</p>${['Depth-first search','Breadth-first search','In-order traversal','Hashing'].map((x,i)=>`<label class="answer"><input type="radio" name="q1" value="${i}" hidden> ${x}</label>`).join('')}</div><div class="quiz-question"><p><strong>02.</strong> What is the average expected lookup complexity of a well-designed hash table?</p>${['O(n)','O(log n)','O(1)','O(n²)'].map((x,i)=>`<label class="answer"><input type="radio" name="q2" value="${i}" hidden> ${x}</label>`).join('')}</div><button class="button primary" data-action="grade-quiz">Finish checkpoint ${icon('arrow')}</button><div id="quiz-result" class="result"></div></div><aside class="assessment-note"><h3>What happens next</h3><p>When connected to your backend, this checkpoint writes to <code>Assessment_Scores</code>, then sends a progress report.</p><div class="send-preview"><div>${icon('mail')} Detailed semester summary via Gmail</div><div>${icon('message')} Milestone notification via WhatsApp</div><div>${icon('check')} Review suggestions saved to your space</div></div></aside></div></div></div>`;}
function projectsModal(){return `<div class="modal-backdrop" data-action="close-modal"><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="projects-title" onclick="event.stopPropagation()"><button class="close" data-action="close-modal" aria-label="Close">${icon('close')}</button><div class="eyebrow">Engineering project blueprint hub</div><h2 id="projects-title">Make the theory tangible.</h2><p>Starter blueprints for practical engineering work. Replace sample resource links with your department’s approved repositories before release.</p><div class="project-list">${[['IoT plant monitor','ESP32 · DHT22 · MQTT','Sensor pinout, wiring notes and a cloud dashboard starter.'],['Campus network planner','CSE · Networks','Design a VLAN layout, subnet plan and security checklist.'],['Smart energy meter','EEE · Embedded','Circuit outline, calibration worksheet and test plan.'],['CAD bridge truss','Civil · Design','Structural model brief, load cases and analysis guide.']].map((p,i)=>`<article class="project"><span class="tag">Blueprint 0${i+1}</span><h3>${p[0]}</h3><p><strong>${p[1]}</strong><br>${p[2]}</p><button class="text-button" style="margin-top:11px" data-action="resource">Open starter pack →</button></article>`).join('')}</div></div></div>`;}
function flashModal(){return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="flash-title" onclick="event.stopPropagation()"><button class="close" data-action="close-modal" aria-label="Close">${icon('close')}</button><div class="eyebrow">Spaced repetition</div><h2 id="flash-title">One idea. Deep recall.</h2><p>Tap the card to flip it. Mark it known after you can explain it without looking.</p><div class="flashcard" id="flashcard"><div class="flash-inner"><div class="flash-face"><span class="tag">DATA STRUCTURES · 03</span><h3>What makes an AVL tree special?</h3><p>Tap to reveal</p></div><div class="flash-face back"><span class="tag" style="color:#c7e896">ANSWER</span><h3>Self-balancing BST</h3><p>Every node maintains a balance factor between −1 and +1, using rotations after insertion or deletion.</p></div></div></div><button class="button primary" data-action="flash-known">${icon('check')} I knew this</button></div></div>`;}
function sandboxModal(){return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="sandbox-title" onclick="event.stopPropagation()"><button class="close" data-action="close-modal" aria-label="Close">${icon('close')}</button><div class="eyebrow">Code & math sandbox</div><h2 id="sandbox-title">Try the idea.</h2><p>Runs compact JavaScript calculations in your browser. It is intentionally offline and has no server access.</p><div class="sandbox"><div class="field"><label for="code-area">JavaScript</label><textarea id="code-area">const nodes = [10, 5, 15, 3, 7];\nconsole.log('Tree nodes:', nodes.length);\nconsole.log('Height estimate:', Math.ceil(Math.log2(nodes.length + 1)));</textarea></div><button class="button primary" data-action="run-code">${icon('play')} Run experiment</button><div class="sandbox-output" id="sandbox-output">Ready.</div><div class="math-output">Mathematical note: h ≈ ⌈log₂(n + 1)⌉</div></div></div></div>`;}
function showOverlay(html){document.body.insertAdjacentHTML('beforeend',html);}
function closeOverlays(){document.querySelectorAll('.modal-backdrop,.drawer-backdrop,.drawer').forEach(el=>el.remove());}
function toast(message){const el=document.getElementById('toast-region');el.innerHTML=`<div class="toast">${icon('check')}<span>${esc(message)}</span></div>`;setTimeout(()=>el.innerHTML='',3300);}
function bindEvents(){document.querySelectorAll('[data-action],[data-scale],[data-layout],[data-login-type],[data-course],[data-sound]').forEach(el=>el.addEventListener('click',handleClick));document.querySelectorAll('input[data-action="topic"]').forEach(el=>el.addEventListener('change',handleTopic));let form=document.getElementById('login-form');if(form)form.addEventListener('submit',handleLogin);let search=document.getElementById('course-search');if(search){search.addEventListener('input',filterCatalog);document.getElementById('degree-filter').addEventListener('change',filterCatalog);document.getElementById('branch-filter').addEventListener('change',filterCatalog);document.getElementById('skill-filter').addEventListener('change',filterCatalog);}document.querySelectorAll('.answer').forEach(l=>l.addEventListener('click',()=>{document.querySelectorAll('.answer').forEach(a=>a.classList.remove('selected'));l.classList.add('selected');l.querySelector('input').checked=true;}));let f=document.getElementById('flashcard');if(f)f.addEventListener('click',()=>f.classList.toggle('flipped'));}
function handleClick(e){const el=e.currentTarget,action=el.dataset.action;if(el.dataset.scale){state.fontScale=el.dataset.scale;saveState();render();return;}if(el.dataset.layout){state.layout=el.dataset.layout;saveState();render();return;}if(el.dataset.loginType){closeOverlays();showOverlay(loginModal(el.dataset.loginType));bindEvents();return;}if(el.dataset.course && !action){state.activeCourse=el.dataset.course;saveState();render();return;}if(el.dataset.sound){state.sound=el.dataset.sound;saveState();render();toast(`${el.textContent} ambience selected for your focus deck.`);return;}switch(action){case'theme':state.theme=state.theme==='dark'?'light':'dark';saveState();render();break;case'login':showOverlay(loginModal('new'));bindEvents();break;case'scroll-paths':document.getElementById('login-paths')?.scrollIntoView({behavior:'smooth'});break;case'home':state.user=null;saveState();render();break;case'close-modal':case'close-drawer':closeOverlays();break;case'drawer':showOverlay(drawer());bindEvents();break;case'primary':state.primary=el.dataset.course;state.activeCourse=el.dataset.course;saveState();render();toast(`${courseById(el.dataset.course).title} is now your primary course.`);break;case'chapter':state.openChapter=state.openChapter===Number(el.dataset.chapter)?-1:Number(el.dataset.chapter);saveState();render();break;case'focus':toggleFocus();break;case'focus-reset':state.focusSeconds=1500;state.isFocusing=false;clearInterval(focusInterval);saveState();render();break;case'assessments':showOverlay(assessmentModal());bindEvents();break;case'projects':showOverlay(projectsModal());bindEvents();break;case'flashcards':showOverlay(flashModal());bindEvents();break;case'sandbox':showOverlay(sandboxModal());bindEvents();break;case'flash-known':toast('Nice recall. This card is scheduled for a later review.');break;case'run-code':runCode();break;case'grade-quiz':gradeQuiz();break;case'video':toast('Lecture playback opens here once your video library is connected.');break;case'resource':toast('Resource library is ready for your approved links and downloads.');break;case'add-course':toggleCourse(el.dataset.course);break;case'profile':toast('Profile preferences are saved with this learning space.');break;}}
function handleTopic(e){const id=state.activeCourse;state.progress[key(id,e.target.dataset.chapter,e.target.dataset.topic)]=e.target.checked;saveState();render();if(e.target.checked){toast('Topic completed - progress updated across your course map.');}}
function handleLogin(e){e.preventDefault();const d=new FormData(e.target);let returning=d.get('mode')==='returning';state.user={name:returning?'Aarav Sharma':d.get('name'),email:d.get('email'),degree:returning?'B.Tech':d.get('degree'),branch:returning?'CSE':d.get('branch')};state.activeCourse=state.primary||'dsa';saveState();closeOverlays();render();toast(returning?'Your saved learning space has been restored.':'Welcome - your first learning space is ready.');}
function toggleCourse(id){let idx=state.selectedCourses.indexOf(id);if(idx>-1){state.selectedCourses.splice(idx,1);if(state.activeCourse===id)state.activeCourse=state.selectedCourses[0]||'dsa';if(state.primary===id)state.primary=state.selectedCourses[0]||null;toast(`${courseById(id).title} removed from your board.`);}else{state.selectedCourses.push(id);state.activeCourse=id;toast(`${courseById(id).title} added to your board.`);}saveState();let list=document.getElementById('catalog-list');if(list)list.innerHTML=catalogItems(filteredCatalog());let footer=document.querySelector('.drawer-footer .button');if(footer)footer.innerHTML=`${icon('check')} ${state.selectedCourses.length} course${state.selectedCourses.length===1?'':'s'} on my board`;bindEvents();}
function filteredCatalog(){let q=(document.getElementById('course-search')?.value||'').toLowerCase(),d=document.getElementById('degree-filter')?.value||'all',b=document.getElementById('branch-filter')?.value||'all',s=document.getElementById('skill-filter')?.value||'all';return courseCatalog.filter(c=>(d==='all'||c.degree===d)&&(b==='all'||c.branch===b)&&(s==='all'||c.skill===s)&&(`${c.title} ${c.description} ${c.branch} ${c.skill}`).toLowerCase().includes(q));}
function filterCatalog(){document.getElementById('catalog-list').innerHTML=catalogItems(filteredCatalog());bindEvents();}
function toggleFocus(){state.isFocusing=!state.isFocusing;clearInterval(focusInterval);if(state.isFocusing){focusInterval=setInterval(()=>{if(state.focusSeconds<=1){state.focusSeconds=300;state.isFocusing=false;clearInterval(focusInterval);toast('Focus session complete. Take five calm minutes.');}else state.focusSeconds--;saveState();let clock=document.querySelector('.focus-clock');if(clock){clock.textContent=`${String(Math.floor(state.focusSeconds/60)).padStart(2,'0')}:${String(state.focusSeconds%60).padStart(2,'0')}`;}},1000);}saveState();render();}
function gradeQuiz(){let q1=document.querySelector('input[name="q1"]:checked')?.value,q2=document.querySelector('input[name="q2"]:checked')?.value;if(q1===undefined||q2===undefined){toast('Choose an answer for both questions first.');return;}let score=(Number(q1)===1?50:0)+(Number(q2)===2?50:0);let result=document.getElementById('quiz-result');result.className='result show';result.innerHTML=`Checkpoint complete: <strong>${score}%</strong>. A ${score===100?'great':'useful'} review plan is ready. <br><span class="micro">GMAIL + WHATSAPP DISPATCH QUEUED IN DEMO MODE</span>`;toast(`Assessment score logged: ${score}%.`);}
function runCode(){let out=document.getElementById('sandbox-output'),code=document.getElementById('code-area').value,logs=[];try{new Function('console',code)({log:(...a)=>logs.push(a.map(v=>typeof v==='object'?JSON.stringify(v):String(v)).join(' '))});out.textContent=logs.join('\n')||'Code ran without output.';}catch(err){out.textContent=`Error: ${err.message}`;}}
setInterval(()=>{if(!state.user){state.quoteIndex=(state.quoteIndex+1)%quotes.length;let t=document.getElementById('quote-text');if(t){t.style.opacity=0;setTimeout(()=>{let q=quotes[state.quoteIndex];t.textContent=`“${q[0]}”`;t.style.opacity=1;let by=document.querySelector('.quote-by > span');if(by)by.textContent=q[1];document.querySelectorAll('.ticker-dots span').forEach((x,i)=>x.classList.toggle('active',i===state.quoteIndex));},220);}}},9000);
/* Fresh account flow, information pages, and notification settings. */
function render(){
  document.body.classList.toggle('light',state.theme==='light');
  document.documentElement.style.setProperty('--font-size',{small:'14px',normal:'16px',large:'18px',xlarge:'20px'}[state.fontScale]);
  const app=document.getElementById('app');
  app.innerHTML=currentView==='summary'?infoPage('summary'):currentView==='contact'?infoPage('contact'):(state.user?dashboard():landing());
  bindEvents();
}

function commonTopbar(dashboard=false){
  const nav=dashboard
    ? `<nav class="dash-menu" aria-label="Site navigation"><button class="nav-link ${currentView==='dashboard'?'active':''}" data-action="dashboard">Learning Space</button><button class="nav-link ${currentView==='summary'?'active':''}" data-action="summary">Website summary</button><button class="nav-link ${currentView==='contact'?'active':''}" data-action="contact">Contact us</button><button class="nav-link" data-action="notifications">Updates</button></nav>`
    : `<nav class="dash-menu public-menu" aria-label="Site navigation"><button class="nav-link ${currentView==='landing'?'active':''}" data-action="landing">Home</button><button class="nav-link ${currentView==='summary'?'active':''}" data-action="summary">Website summary</button><button class="nav-link ${currentView==='contact'?'active':''}" data-action="contact">Contact us</button></nav>`;
  const controls=`<button class="icon-button" data-action="theme" aria-label="Toggle colour theme">${state.theme==='dark'?icon('sun'):icon('moon')}</button><button class="scale-button ${state.fontScale==='small'?'active':''}" data-scale="small">A−</button><button class="scale-button ${state.fontScale==='normal'?'active':''}" data-scale="normal">A</button><button class="scale-button ${state.fontScale==='large'?'active':''}" data-scale="large">A+</button><button class="scale-button ${state.fontScale==='xlarge'?'active':''}" data-scale="xlarge">A++</button>`;
  if(dashboard){
    return `<header class="dash-nav shell"><a class="brand" href="#" data-action="dashboard"><span class="brand-mark">${icon('leaf')}</span><span>Engineering OS</span></a>${nav}<div class="nav-tools">${controls}<button class="profile" data-action="profile" aria-label="Open learning preferences"><span class="avatar">${initials(state.user.name)}</span><span class="profile-text"><small>LEARNER</small><strong>${esc(state.user.name)}</strong></span></button></div></header>`;
  }
  return `<header class="topbar shell"><a class="brand" href="#" data-action="landing"><span class="brand-mark">${icon('leaf')}</span><span>Personal Engineering OS</span></a>${nav}<div class="nav-tools">${controls}<button class="icon-button only-mobile" data-action="login" aria-label="Sign in">${icon('arrow')}</button></div></header>`;
}

function landing(){
  const q=quotes[state.quoteIndex];
  return `<div class="shell">${commonTopbar()}<section class="hero"><video class="hero-video" autoplay muted loop playsinline aria-hidden="true"><source src="https://videos.pexels.com/video-files/3195394/3195394-uhd_2560_1440_25fps.mp4" type="video/mp4"></video><div class="hero-fallback" aria-hidden="true"></div><div class="hero-overlay" aria-hidden="true"></div><div class="hero-content"><div><div class="eyebrow">A calmer way to engineer</div><h1>Find your <em>focus.</em><br>Build your future.</h1><p class="hero-copy">A personal learning system built for the way engineers really work: one topic, one session, one meaningful milestone at a time.</p><div class="cta-row"><button class="button primary" data-action="login">Start Learning Courses ${icon('arrow')}</button><button class="button ghost" data-action="summary">See how it works</button></div></div><aside class="quote-card" aria-live="polite"><div>${icon('quote')}</div><div class="quote-text" id="quote-text">“${q[0]}”</div><div class="quote-by"><span>${q[1]}</span><span class="ticker-dots">${quotes.map((_,i)=>`<span class="${i===state.quoteIndex?'active':''}"></span>`).join('')}</span></div></aside></div><div class="login-paths" id="login-paths"><button class="path-card" data-login-type="new"><span class="path-label">01 · New student</span><strong>Create a new learning account</strong><span>Choose a User ID and 4-digit PIN, then add your contact details.</span></button><button class="path-card" data-login-type="returning"><span class="path-label">02 · User login</span><strong>Continue your learning journey</strong><span>Sign in securely with your User ID and 4-digit PIN.</span></button></div><footer class="landing-footer"><span><i class="status-dot"></i> Your progress stays with you</span><span>LOCAL-FIRST LEARNING SPACE</span></footer></section></div>`;
}

function infoPage(kind){
  const isContact=kind==='contact';
  const heading=isContact?'Talk to the learning team.':'A learning system with room to breathe.';
  const intro=isContact?'Tell us what would make your study experience work better. This demo keeps the message in this browser only.':'Personal Engineering OS combines an adaptable curriculum map with a calm workspace, so students can plan, practise and see their own progress.';
  const cards=isContact
    ? `<article class="info-card bento"><span class="tag">STUDENT SUPPORT</span><h3>Help with your learning space</h3><p>Questions about courses, progress, or study tools can start here.</p><p class="contact-line">support@engineering-os.example</p></article><article class="info-card bento"><span class="tag">PARTNERSHIPS</span><h3>For colleges and mentors</h3><p>Bring a curriculum, project repository or assessment workflow into one calm student space.</p><p class="contact-line">partners@engineering-os.example</p></article>`
    : `<article class="info-card bento"><span class="tag">01 · DISCOVER</span><h3>Build the right board.</h3><p>Browse programme pathways from the supplied engineering master curriculum, then select the subjects that matter now.</p></article><article class="info-card bento"><span class="tag">02 · LEARN</span><h3>Keep the next step clear.</h3><p>Topic checklists cascade through chapters and semesters while a focused timer keeps the session intentional.</p></article><article class="info-card bento"><span class="tag">03 · APPLY</span><h3>Turn study into practice.</h3><p>Use short checkpoints, flashcards, code experiments and blueprint starters to make concepts tangible.</p></article>`;
  return `<div class="info-page">${commonTopbar(Boolean(state.user))}<main class="shell info-main"><section class="info-hero"><div class="eyebrow">${isContact?'CONTACT US':'WEBSITE SUMMARY'}</div><h1>${heading}</h1><p>${intro}</p>${isContact?`<form id="contact-form" class="contact-form bento"><div class="form-grid"><div class="field"><label for="contact-name">Name</label><input id="contact-name" name="name" required placeholder="Your name"></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" required placeholder="you@example.com"></div><div class="field full"><label for="contact-message">How can we help?</label><textarea id="contact-message" name="message" required placeholder="Write your message here"></textarea></div></div><button class="button primary" type="submit">Save my message locally ${icon('arrow')}</button><p class="form-hint">No email is sent from this demo page.</p></form>`:`<div class="info-actions"><button class="button primary" data-action="login">Create a learning account ${icon('arrow')}</button><button class="button ghost info-ghost" data-action="contact">Contact us</button></div>`}</section><section class="info-grid ${isContact?'two-up':''}">${cards}</section>${!isContact?`<section class="bento summary-strip"><div><span class="tag">PRIVACY NOTE</span><h3>Your data, with a clear boundary.</h3><p>Until a backend is connected, accounts, PINs and progress stay in this browser. A production build must store PINs only as secure server-side hashes.</p></div><button class="text-button" data-action="contact">Ask a question →</button></section>`:''}</main></div>`;
}

function loginModal(type='new'){
  const isNew=type==='new';
  return `<div class="modal-backdrop" data-action="close-modal"><div class="modal account-modal" role="dialog" aria-modal="true" aria-labelledby="login-title" onclick="event.stopPropagation()"><button class="close" data-action="close-modal" aria-label="Close">${icon('close')}</button><div class="eyebrow">Secure study entry</div><h2 id="login-title">${isNew?'Create your learner account.':'Welcome back.'}</h2><p>${isNew?'Use one simple User ID and a four-digit PIN to keep your learning space yours.':'Enter the User ID and four-digit PIN you created when registering.'}</p><div class="login-options"><button class="login-option ${isNew?'selected':''}" data-login-type="new"><strong>New registration</strong><span>Create your account and choose optional updates.</span></button><button class="login-option ${!isNew?'selected':''}" data-login-type="returning"><strong>User login</strong><span>Open an existing learning space.</span></button></div><form id="login-form" novalidate><input type="hidden" name="mode" value="${type}"><div class="form-grid">${isNew?`<div class="field"><label for="name">Full name</label><input id="name" name="name" autocomplete="name" placeholder="Your name" required></div>`:''}<div class="field"><label for="user-id">User ID</label><input id="user-id" name="userId" autocomplete="username" placeholder="e.g. aarav.cse" minlength="3" maxlength="24" required></div><div class="field"><label for="pin">Create 4-digit PIN</label><input id="pin" name="pin" type="password" inputmode="numeric" autocomplete="${isNew?'new-password':'current-password'}" pattern="[0-9]{4}" maxlength="4" placeholder="••••" required></div>${isNew?`<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@college.edu" required></div><div class="field"><label for="phone">Mobile number</label><input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="10-digit mobile number" pattern="[0-9+ ()-]{10,18}" required></div><div class="field"><label for="degree">Degree</label><select id="degree" name="degree"><option>B.Tech</option><option>Diploma</option><option>B.Sc</option><option>M.Tech</option></select></div><div class="field"><label for="branch">Branch</label><select id="branch" name="branch"><option>CSE</option><option>ECE</option><option>EEE</option><option>Mechanical</option><option>Civil</option><option>Multi-disciplinary</option></select></div><label class="notify-option full"><input type="checkbox" name="notify" value="yes"><span><strong>Enable milestone updates</strong><small>Optional confirmation messages for registration and completed courses by email and mobile.</small></span></label>`:''}</div><div id="login-error" class="form-error" role="alert"></div><div class="form-note">${icon('lock')} <span>Demo mode stores account details only in this browser. A production release should authenticate through a secure server and never store a PIN in the browser.</span></div><button class="button primary" type="submit">${isNew?'Create my account':'Open my learning space'} ${icon('arrow')}</button></form></div></div>`;
}

function notificationModal(){
  const pref=state.user?.notifications||{enabled:false,email:false,sms:false};
  return `<div class="modal-backdrop" data-action="close-modal"><div class="modal settings-modal" role="dialog" aria-modal="true" aria-labelledby="settings-title" onclick="event.stopPropagation()"><button class="close" data-action="close-modal" aria-label="Close">${icon('close')}</button><div class="eyebrow">Optional updates</div><h2 id="settings-title">Milestone messages</h2><p>Choose whether this learner should receive confirmation when a course is completed. The demo does not send external messages.</p><form id="notify-form" class="settings-list"><label class="notify-option"><input type="checkbox" name="enabled" ${pref.enabled?'checked':''}><span><strong>Enable milestone confirmations</strong><small>Keep this off for a quiet, in-app-only learning space.</small></span></label><label class="notify-option"><input type="checkbox" name="email" ${pref.email?'checked':''}><span><strong>Email</strong><small>${esc(state.user?.email||'No email registered')}</small></span></label><label class="notify-option"><input type="checkbox" name="sms" ${pref.sms?'checked':''}><span><strong>Mobile message</strong><small>${state.user?.phone?`Registered number ending ${esc(state.user.phone.replace(/\D/g,'').slice(-4))}`:'No mobile number registered'}</small></span></label><button class="button primary" type="submit">Save update preference ${icon('check')}</button></form></div></div>`;
}

function bindEvents(){
  document.querySelectorAll('[data-action],[data-scale],[data-layout],[data-login-type],[data-course],[data-sound]').forEach(el=>el.addEventListener('click',handleClick));
  document.querySelectorAll('input[data-action="topic"]').forEach(el=>el.addEventListener('change',handleTopic));
  document.getElementById('login-form')?.addEventListener('submit',handleLogin);
  document.getElementById('notify-form')?.addEventListener('submit',handleNotificationSettings);
  document.getElementById('contact-form')?.addEventListener('submit',handleContact);
  const search=document.getElementById('course-search');
  if(search){search.addEventListener('input',filterCatalog);document.getElementById('degree-filter').addEventListener('change',filterCatalog);document.getElementById('branch-filter').addEventListener('change',filterCatalog);document.getElementById('skill-filter').addEventListener('change',filterCatalog);}
  document.querySelectorAll('.answer').forEach(l=>l.addEventListener('click',()=>{document.querySelectorAll('.answer').forEach(a=>a.classList.remove('selected'));l.classList.add('selected');l.querySelector('input').checked=true;}));
  document.getElementById('flashcard')?.addEventListener('click',e=>e.currentTarget.classList.toggle('flipped'));
}

function showFormError(message){const target=document.getElementById('login-error');if(target)target.textContent=message;}
function handleLogin(e){
  e.preventDefault(); const d=new FormData(e.currentTarget); const isNew=d.get('mode')==='new';
  const userId=String(d.get('userId')||'').trim(); const pin=String(d.get('pin')||'').trim();
  if(!/^[a-zA-Z0-9._-]{3,24}$/.test(userId)){showFormError('Use 3–24 letters, numbers, dots, hyphens or underscores for your User ID.');return;}
  if(!/^\d{4}$/.test(pin)){showFormError('Your PIN must contain exactly four digits.');return;}
  const users=Array.isArray(state.registeredUsers)?state.registeredUsers:[];
  if(isNew){
    if(!String(d.get('name')||'').trim()){showFormError('Please enter your full name.');return;}
    if(users.some(u=>String(u.userId||'').toLowerCase()===userId.toLowerCase())){showFormError('That User ID is already registered. Please choose another.');return;}
    const updates=d.get('notify')==='yes';
    const user={name:String(d.get('name')).trim(),userId,pin,email:String(d.get('email')).trim(),phone:String(d.get('phone')).trim(),degree:d.get('degree'),branch:d.get('branch'),notifications:{enabled:updates,email:updates,sms:updates}};
    state.registeredUsers=[...users,user]; state.user=user;
    state.activeCourse=state.primary||'dsa'; saveState(); closeOverlays(); currentView='dashboard'; render();
    toast(updates?'Registration complete. Email and mobile confirmations are enabled in demo mode.':'Registration complete. Your learning space is ready.');
    return;
  }
  const user=users.find(u=>String(u.userId||'').toLowerCase()===userId.toLowerCase()&&String(u.pin||'')===pin);
  if(!user){showFormError('That User ID and PIN do not match. Register first if you are new here.');return;}
  state.user=user; state.activeCourse=state.primary||'dsa'; saveState(); closeOverlays(); currentView='dashboard'; render(); toast('Welcome back - your saved learning space has been restored.');
}

function handleNotificationSettings(e){
  e.preventDefault(); const d=new FormData(e.currentTarget); const notifications={enabled:d.get('enabled')==='on',email:d.get('email')==='on',sms:d.get('sms')==='on'};
  if(!notifications.enabled){notifications.email=false;notifications.sms=false;}
  state.user.notifications=notifications;
  state.registeredUsers=(state.registeredUsers||[]).map(u=>u.userId===state.user.userId?{...u,notifications}:u);
  saveState();closeOverlays();render();toast(notifications.enabled?'Milestone updates are enabled in demo mode.':'Milestone updates are turned off.');
}

function handleContact(e){e.preventDefault();e.currentTarget.reset();toast('Your message was saved locally. No external email was sent.');}
function handleTopic(e){
  const id=state.activeCourse; state.progress[key(id,e.target.dataset.chapter,e.target.dataset.topic)]=e.target.checked; saveState(); render();
  if(e.target.checked){
    if(percent(id)===100&&state.user?.notifications?.enabled){toast(`Course complete! Demo confirmation is ready for ${state.user.notifications.email?'email':''}${state.user.notifications.email&&state.user.notifications.sms?' and ':''}${state.user.notifications.sms?'mobile':''}.`);}
    else toast('Topic completed - progress updated across your course map.');
  }
}

function handleClick(e){
  const el=e.currentTarget,action=el.dataset.action;
  if(el.dataset.scale){state.fontScale=el.dataset.scale;saveState();render();return;}
  if(el.dataset.layout){state.layout=el.dataset.layout;saveState();render();return;}
  if(el.dataset.loginType){closeOverlays();showOverlay(loginModal(el.dataset.loginType));bindEvents();return;}
  if(el.dataset.course&&!action){state.activeCourse=el.dataset.course;saveState();render();return;}
  if(el.dataset.sound){state.sound=el.dataset.sound;saveState();render();toast(`${el.textContent} ambience selected for your focus deck.`);return;}
  switch(action){
    case'theme':state.theme=state.theme==='dark'?'light':'dark';saveState();render();break;
    case'landing':currentView='landing';render();break;
    case'dashboard':currentView=state.user?'dashboard':'landing';render();break;
    case'summary':currentView='summary';render();break;
    case'contact':currentView='contact';render();break;
    case'login':showOverlay(loginModal('new'));bindEvents();break;
    case'scroll-paths':document.getElementById('login-paths')?.scrollIntoView({behavior:'smooth'});break;
    case'home':currentView=state.user?'dashboard':'landing';render();break;
    case'close-modal':case'close-drawer':closeOverlays();break;
    case'drawer':showOverlay(drawer());bindEvents();break;
    case'primary':state.primary=el.dataset.course;state.activeCourse=el.dataset.course;saveState();render();toast(`${courseById(el.dataset.course).title} is now your primary course.`);break;
    case'chapter':state.openChapter=state.openChapter===Number(el.dataset.chapter)?-1:Number(el.dataset.chapter);saveState();render();break;
    case'focus':toggleFocus();break;
    case'focus-reset':state.focusSeconds=1500;state.isFocusing=false;clearInterval(focusInterval);saveState();render();break;
    case'assessments':showOverlay(assessmentModal());bindEvents();break;
    case'projects':showOverlay(projectsModal());bindEvents();break;
    case'flashcards':showOverlay(flashModal());bindEvents();break;
    case'sandbox':showOverlay(sandboxModal());bindEvents();break;
    case'flash-known':toast('Nice recall. This card is scheduled for a later review.');break;
    case'run-code':runCode();break;
    case'grade-quiz':gradeQuiz();break;
    case'video':toast('Lecture playback opens here once your video library is connected.');break;
    case'resource':toast('Resource library is ready for your approved links and downloads.');break;
    case'add-course':toggleCourse(el.dataset.course);break;
    case'notifications':case'profile':showOverlay(notificationModal());bindEvents();break;
  }
}

render();
